const f=n=>{n=[...n];const s=n.filter(e=>e.matches('[name="CRAFT_CSRF_TOKEN"]')),o=n.filter(e=>e.matches("craft-csrf-input"));fetch("/index.php?p=actions/users/session-info",{headers:{Accept:"application/json"}}).then(e=>e.json()).then(e=>{s.length&&s.forEach(c=>{c.value=e.csrfTokenValue}),o.length&&o.forEach(c=>{const t=document.createElement("input");t.type="hidden",t.name=e.csrfTokenName,t.value=e.csrfTokenValue,c.replaceWith(t)}),window.csrfTokenValue=e.csrfTokenValue})};export{f as default};
